import type { AnimatedGlyph } from './types.ts'

export class Renderer {
  private ctx: CanvasRenderingContext2D
  private canvas: HTMLCanvasElement
  private dpr: number = 1

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d')!
    this.resize()
  }

  resize() {
    this.dpr = window.devicePixelRatio || 1
    const rect = this.canvas.getBoundingClientRect()
    const w = Math.max(1, rect.width)
    const h = Math.max(1, rect.height)
    this.canvas.width = w * this.dpr
    this.canvas.height = h * this.dpr
    this.ctx.scale(this.dpr, this.dpr)
  }

  get width() {
    return this.canvas.width / this.dpr
  }

  get height() {
    return this.canvas.height / this.dpr
  }

  clear() {
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0)
    this.ctx.clearRect(0, 0, this.width, this.height)
    this.ctx.fillStyle = '#0a0a0a'
    this.ctx.fillRect(0, 0, this.width, this.height)
  }

  drawGlyphs(glyphs: AnimatedGlyph[], font: string, color: string = '#f0f0f0') {
    const ctx = this.ctx

    ctx.font = font
    ctx.textBaseline = 'top'

    // Batch: render simple glyphs (no rotation, scale ~1, full opacity) together
    // and per-glyph transform for the rest
    for (const glyph of glyphs) {
      if (glyph.opacity <= 0.005) continue

      const needsTransform = Math.abs(glyph.rotation) > 0.001 || Math.abs(glyph.scale - 1) > 0.001

      if (needsTransform) {
        ctx.save()
        ctx.translate(glyph.x + glyph.width / 2, glyph.y)
        ctx.rotate(glyph.rotation)
        ctx.scale(glyph.scale, glyph.scale)
        ctx.globalAlpha = glyph.opacity
        ctx.fillStyle = color
        ctx.fillText(glyph.char, -glyph.width / 2, 0)
        ctx.restore()
      } else {
        ctx.globalAlpha = glyph.opacity
        ctx.fillStyle = color
        ctx.fillText(glyph.char, glyph.x, glyph.y)
      }
    }

    ctx.globalAlpha = 1
  }

  // Draw a subtle guide showing the container width
  drawWidthGuide(x: number, y: number, width: number, height: number) {
    const ctx = this.ctx
    ctx.strokeStyle = 'rgba(255,255,255,0.04)'
    ctx.lineWidth = 1
    ctx.setLineDash([4, 4])
    ctx.strokeRect(x, y, width, height)
    ctx.setLineDash([])
  }
}

import type { GlyphPosition, AnimatedGlyph, EffectFn, EffectParams, EffectName } from './types.ts'
import { easings } from './easing.ts'

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t
}

function clamp(v: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, v))
}

function glyphToAnimated(g: GlyphPosition, opacity = 1, scale = 1, rotation = 0): AnimatedGlyph {
  return { char: g.char, x: g.x, y: g.y, width: g.width, opacity, scale, rotation }
}

// === MORPH ===
// Smooth interpolation between two layout positions
const morph: EffectFn = (from, to, t, _time, params) => {
  const ease = easings[params.easing]
  const result: AnimatedGlyph[] = []
  const maxLen = Math.max(from.length, to.length)

  for (let i = 0; i < maxLen; i++) {
    const f = from[i]
    const tg = to[i]

    if (f && tg) {
      // Both exist — interpolate
      const staggerOffset = params.stagger > 0 ? (i / maxLen) * (params.stagger / 100) : 0
      const localT = clamp((t - staggerOffset) / (1 - staggerOffset + 0.001), 0, 1)
      const et = ease(localT)

      result.push({
        char: tg.char,
        x: lerp(f.x, tg.x, et),
        y: lerp(f.y, tg.y, et),
        width: lerp(f.width, tg.width, et),
        opacity: 1,
        scale: 1,
        rotation: 0,
      })
    } else if (tg) {
      // New glyph in target — fade in
      const localT = clamp((t - 0.5) * 2, 0, 1)
      result.push(glyphToAnimated(tg, ease(localT)))
    } else if (f) {
      // Glyph removed — fade out
      const localT = clamp(t * 2, 0, 1)
      result.push(glyphToAnimated(f, 1 - ease(localT)))
    }
  }

  return result
}

// === EXPLODE ===
// Characters scatter outward from center with rotation
const explode: EffectFn = (from, to, t, _time, params) => {
  const ease = easings[params.easing]
  const result: AnimatedGlyph[] = []

  // Find center of the "from" layout
  let cx = 0, cy = 0
  for (const g of from) { cx += g.x; cy += g.y }
  cx /= from.length || 1
  cy /= from.length || 1

  const radius = params.scatterRadius
  const rotIntensity = params.rotationIntensity

  for (let i = 0; i < from.length; i++) {
    const f = from[i]!
    const staggerOffset = params.stagger > 0 ? (i / from.length) * (params.stagger / 100) : 0
    const localT = clamp((t - staggerOffset) / (1 - staggerOffset + 0.001), 0, 1)
    const et = ease(localT)

    // Direction from center
    const dx = f.x - cx
    const dy = f.y - cy
    const dist = Math.sqrt(dx * dx + dy * dy) || 1
    const angle = Math.atan2(dy, dx)

    // Add some randomness (seeded by index)
    const seed = Math.sin(i * 127.1 + 311.7) * 43758.5453
    const randAngle = (seed - Math.floor(seed)) * Math.PI * 2
    const randRadius = ((Math.sin(i * 269.5 + 183.3) * 43758.5453) % 1) * 0.5 + 0.75

    const scatterX = Math.cos(angle + randAngle * 0.3) * radius * randRadius * et
    const scatterY = Math.sin(angle + randAngle * 0.3) * radius * randRadius * et

    result.push({
      char: f.char,
      x: f.x + scatterX,
      y: f.y + scatterY,
      width: f.width,
      opacity: 1 - et * 0.8,
      scale: 1 + et * 0.5,
      rotation: et * rotIntensity * (i % 2 === 0 ? 1 : -1),
    })
  }

  return result
}

// === POUR / CASCADE ===
// Glyphs fall from above into their final positions, staggered by line and x
const pour: EffectFn = (_from, to, t, _time, params) => {
  const ease = easings[params.easing]
  const result: AnimatedGlyph[] = []

  if (to.length === 0) return result

  const maxLine = to[to.length - 1]!.lineIndex

  for (let i = 0; i < to.length; i++) {
    const tg = to[i]!
    // Stagger: earlier lines and left-most characters arrive first
    const lineDelay = maxLine > 0 ? (tg.lineIndex / (maxLine + 1)) * 0.6 : 0
    const xDelay = (tg.x / 1000) * 0.15
    const totalDelay = lineDelay + xDelay
    const localT = clamp((t - totalDelay) / (1 - totalDelay + 0.001), 0, 1)
    const et = ease(localT)

    const startY = tg.y - 300 - Math.random() * 100

    result.push({
      char: tg.char,
      x: tg.x,
      y: lerp(startY, tg.y, et),
      width: tg.width,
      opacity: et,
      scale: lerp(0.3, 1, et),
      rotation: lerp(-0.5 * (i % 2 === 0 ? 1 : -1), 0, et),
    })
  }

  return result
}

// === WAVE ===
// Continuous sine wave displacement — not a transition, an idle animation
const wave: EffectFn = (_from, to, _t, time, params) => {
  const result: AnimatedGlyph[] = []
  const amp = params.waveAmplitude
  const freq = params.waveFrequency
  const speed = params.waveSpeed

  for (let i = 0; i < to.length; i++) {
    const tg = to[i]!
    const phase = i * freq * 0.1 + time * speed * 0.001
    const yOffset = Math.sin(phase) * amp
    const xOffset = Math.cos(phase * 0.7) * amp * 0.3

    result.push({
      char: tg.char,
      x: tg.x + xOffset,
      y: tg.y + yOffset,
      width: tg.width,
      opacity: 1,
      scale: 1 + Math.sin(phase * 1.3) * 0.05,
      rotation: Math.sin(phase * 0.8) * 0.05,
    })
  }

  return result
}

// === TYPEWRITER ===
// Characters appear one by one with a cursor-like reveal
const typewriter: EffectFn = (_from, to, t, _time, params) => {
  const ease = easings[params.easing]
  const result: AnimatedGlyph[] = []

  for (let i = 0; i < to.length; i++) {
    const tg = to[i]!
    const threshold = i / to.length
    const localT = clamp((t - threshold) * to.length * 0.3, 0, 1)
    const et = ease(localT)

    result.push({
      char: tg.char,
      x: tg.x,
      y: tg.y + (1 - et) * 8,
      width: tg.width,
      opacity: et,
      scale: lerp(0.8, 1, et),
      rotation: 0,
    })
  }

  return result
}

// === VORTEX ===
// Characters spiral inward/outward from a central point, landing exactly at target positions
const vortex: EffectFn = (_from, to, t, _time, params) => {
  const ease = easings[params.easing]
  const result: AnimatedGlyph[] = []

  if (to.length === 0) return result

  // Center of target layout
  let cx = 0, cy = 0
  for (const g of to) { cx += g.x + g.width / 2; cy += g.y }
  cx /= to.length
  cy /= to.length

  for (let i = 0; i < to.length; i++) {
    const tg = to[i]!
    const staggerOffset = params.stagger > 0 ? (i / to.length) * (params.stagger / 100) : 0
    const localT = clamp((t - staggerOffset) / (1 - staggerOffset + 0.001), 0, 1)
    const et = ease(localT)

    // Compute spiral start position (at t=0, all glyphs orbit near center)
    const dx = tg.x - cx
    const dy = tg.y - cy
    const dist = Math.sqrt(dx * dx + dy * dy)
    const angle = Math.atan2(dy, dx)
    const spiralAngle = angle + (1 - et) * Math.PI * 3
    const spiralDist = dist * (1 - et)

    // Spiral position: offset from the final target, NOT reconstructed from polar
    const spiralX = cx + Math.cos(spiralAngle) * spiralDist
    const spiralY = cy + Math.sin(spiralAngle) * spiralDist

    // Lerp between spiral position and exact target — guarantees clean landing
    result.push({
      char: tg.char,
      x: lerp(spiralX, tg.x, et),
      y: lerp(spiralY, tg.y, et),
      width: tg.width,
      opacity: clamp(et * 2, 0, 1),
      scale: lerp(0.1, 1, et),
      rotation: (1 - et) * Math.PI * 2 * (i % 2 === 0 ? 1 : -1),
    })
  }

  return result
}

export const effects: Record<EffectName, EffectFn> = {
  morph,
  explode,
  pour,
  wave,
  typewriter,
  vortex,
}

import { prepareWithSegments, layoutWithLines, type PreparedTextWithSegments } from '@chenglou/pretext'
import type { GlyphPosition } from './types.ts'
import { computeGlyphPositions } from './layout-mapper.ts'

type LavaGlyph = GlyphPosition & {
  // Spring physics state
  dx: number  // displacement x
  dy: number  // displacement y
  vx: number  // velocity x
  vy: number  // velocity y
}

type LayoutMode = 'two-col' | 'three-col' | 'asymmetric' | 'single'

export type LavaParams = {
  radius: number
  force: number
  spring: number
  damping: number
  heatEnabled: boolean
  rotateEnabled: boolean
  layout: LayoutMode
}

export class LavaExperiment {
  private canvas: HTMLCanvasElement
  private ctx: CanvasRenderingContext2D
  private dpr: number = 1
  private glyphs: LavaGlyph[] = []
  private prepared: PreparedTextWithSegments | null = null
  private text: string = ''
  private rafId: number = 0
  private mouseX: number = -9999
  private mouseY: number = -9999
  private running: boolean = false
  private contentTop: number = 0
  private contentBottom: number = 0

  params: LavaParams = {
    radius: 140,
    force: 150,
    spring: 20,
    damping: 0.75,
    heatEnabled: false,
    rotateEnabled: true,
    layout: 'two-col',
  }

  private fontSize = 16
  private lineHeight = 26
  private font = '400 16px "Playfair Display", Georgia, serif'

  setFontSize(size: number) {
    this.fontSize = size
    this.lineHeight = Math.round(size * 1.6)
    this.font = `400 ${size}px "Playfair Display", Georgia, serif`
    if (this.text) { this.prepare(); this.recomputeLayout() }
  }

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d')!
    this.resize()

    this.canvas.addEventListener('mousemove', (e) => {
      const rect = this.canvas.getBoundingClientRect()
      this.mouseX = e.clientX - rect.left
      this.mouseY = e.clientY - rect.top
    })
    this.canvas.addEventListener('mouseleave', () => {
      this.mouseX = -9999
      this.mouseY = -9999
    })
  }

  resize() {
    this.dpr = window.devicePixelRatio || 1
    const rect = this.canvas.getBoundingClientRect()
    const w = Math.max(1, rect.width)
    const h = Math.max(1, rect.height)
    this.canvas.width = w * this.dpr
    this.canvas.height = h * this.dpr
    if (this.text) { this.prepare(); this.recomputeLayout() }
  }

  get width() { return this.canvas.width / this.dpr }
  get height() { return this.canvas.height / this.dpr }

  setText(text: string) {
    this.text = text
    this.prepare()
    this.recomputeLayout()
  }

  setLayout(layout: LayoutMode) {
    this.params.layout = layout
    if (this.prepared) this.recomputeLayout()
  }

  private prepare() {
    this.prepared = prepareWithSegments(this.text, this.font)
  }

  private recomputeLayout() {
    if (!this.prepared) return

    const padding = 60
    const gap = 40
    const availWidth = this.width - padding * 2

    let columns: { x: number; width: number }[] = []

    switch (this.params.layout) {
      case 'two-col': {
        const colW = (availWidth - gap) / 2
        columns = [
          { x: padding, width: colW },
          { x: padding + colW + gap, width: colW },
        ]
        break
      }
      case 'three-col': {
        const colW = (availWidth - gap * 2) / 3
        columns = [
          { x: padding, width: colW },
          { x: padding + colW + gap, width: colW },
          { x: padding + (colW + gap) * 2, width: colW },
        ]
        break
      }
      case 'asymmetric': {
        const sideW = availWidth * 0.32
        const mainW = availWidth - sideW - gap
        columns = [
          { x: padding, width: sideW },
          { x: padding + sideW + gap, width: mainW },
        ]
        break
      }
      case 'single': {
        const colW = Math.min(availWidth, 560)
        const offsetX = (this.width - colW) / 2
        columns = [{ x: offsetX, width: colW }]
        break
      }
    }

    // First pass: compute glyphs at y=0, then find total height to center
    const allGlyphs: GlyphPosition[] = []
    let textOffset = 0
    const fullText = this.text
    const totalWidth = columns.reduce((s, c) => s + c.width, 0)

    for (let ci = 0; ci < columns.length; ci++) {
      const col = columns[ci]!
      const proportion = col.width / totalWidth
      const charCount = Math.round(fullText.length * proportion)
      const colText = ci === columns.length - 1
        ? fullText.slice(textOffset)
        : fullText.slice(textOffset, textOffset + charCount)

      if (!colText.trim()) continue

      const colPrepared = prepareWithSegments(colText, this.font)
      const colGlyphs = computeGlyphPositions(
        colPrepared, col.width, this.lineHeight, col.x, 0, this.font
      )

      for (const g of colGlyphs) {
        g.globalIndex += textOffset
        allGlyphs.push(g)
      }

      textOffset += colText.length
    }

    // Find max y extent across all columns, then center vertically
    let maxY = 0
    for (const g of allGlyphs) {
      const bottom = g.y + this.lineHeight
      if (bottom > maxY) maxY = bottom
    }
    const offsetY = Math.max(0, (this.height - maxY) / 2)
    for (const g of allGlyphs) {
      g.y += offsetY
    }
    this.contentTop = offsetY
    this.contentBottom = offsetY + maxY

    // Convert to LavaGlyphs, preserving existing physics state where possible
    const oldMap = new Map<number, LavaGlyph>()
    for (const g of this.glyphs) oldMap.set(g.globalIndex, g)

    this.glyphs = allGlyphs.map(g => {
      const old = oldMap.get(g.globalIndex)
      return {
        ...g,
        dx: old?.dx ?? 0,
        dy: old?.dy ?? 0,
        vx: old?.vx ?? 0,
        vy: old?.vy ?? 0,
      }
    })
  }

  start() {
    if (this.running) return
    this.running = true
    this.tick()
  }

  stop() {
    this.running = false
    if (this.rafId) {
      cancelAnimationFrame(this.rafId)
      this.rafId = 0
    }
  }

  private tick = () => {
    if (!this.running) { this.rafId = 0; return }

    this.updatePhysics()
    this.render()

    this.rafId = requestAnimationFrame(this.tick)
  }

  private updatePhysics() {
    const { radius, force, spring, damping } = this.params
    const springK = spring * 0.04  // much stiffer spring
    const dampK = damping / 100
    const radiusSq = radius * radius

    for (const g of this.glyphs) {
      // Cursor repulsion — inverse square falloff for magnetic feel
      const gCenterX = g.x + g.width / 2 + g.dx
      const gCenterY = g.y + this.fontSize / 2 + g.dy
      const dxMouse = gCenterX - this.mouseX
      const dyMouse = gCenterY - this.mouseY
      const distSq = dxMouse * dxMouse + dyMouse * dyMouse

      if (distSq < radiusSq && distSq > 1) {
        const dist = Math.sqrt(distSq)
        const normDist = dist / radius
        // Inverse-square-ish: very strong up close, drops fast
        const strength = force * 0.4 * Math.pow(1 - normDist, 2) / (normDist + 0.1)
        g.vx += (dxMouse / dist) * strength
        g.vy += (dyMouse / dist) * strength
      }

      // Spring back to origin (stiff)
      g.vx -= g.dx * springK
      g.vy -= g.dy * springK

      // Damping
      g.vx *= dampK
      g.vy *= dampK

      // Integrate
      g.dx += g.vx
      g.dy += g.vy
    }
  }

  private render() {
    const ctx = this.ctx
    const dpr = this.dpr

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, this.width, this.height)
    ctx.fillStyle = '#0a0a0a'
    ctx.fillRect(0, 0, this.width, this.height)

    ctx.font = this.font
    ctx.textBaseline = 'top'

    const { radius, heatEnabled, rotateEnabled } = this.params
    const radiusSq = radius * radius

    for (const g of this.glyphs) {
      const px = g.x + g.dx
      const py = g.y + g.dy

      // Distance to cursor for heat effect
      const dxMouse = (g.x + g.width / 2 + g.dx) - this.mouseX
      const dyMouse = (g.y + this.fontSize / 2 + g.dy) - this.mouseY
      const distSq = dxMouse * dxMouse + dyMouse * dyMouse

      let color = '#e8e4de'
      let rotation = 0

      if (heatEnabled && distSq < radiusSq * 2.25) {
        const dist = Math.sqrt(distSq)
        const norm = dist / radius
        // Discrete color bands: orange (closest) → yellow → white (far)
        if (norm < 0.4) {
          color = '#ff6b2b'  // hot orange
        } else if (norm < 0.7) {
          color = '#ffb830'  // warm yellow
        } else if (norm < 1.0) {
          color = '#fff1cc'  // warm white
        }
        // beyond 1.0 stays default #e8e4de
      }

      if (rotateEnabled) {
        const displacement = Math.sqrt(g.dx * g.dx + g.dy * g.dy)
        rotation = displacement * 0.008 * (g.globalIndex % 2 === 0 ? 1 : -1)
      }

      if (Math.abs(rotation) > 0.001) {
        ctx.save()
        ctx.translate(px + g.width / 2, py + this.fontSize / 2)
        ctx.rotate(rotation)
        ctx.fillStyle = color
        ctx.fillText(g.char, -g.width / 2, -this.fontSize / 2)
        ctx.restore()
      } else {
        ctx.fillStyle = color
        ctx.fillText(g.char, px, py)
      }
    }

    // Draw subtle column dividers
    this.drawColumnGuides(ctx)
  }

  private drawColumnGuides(ctx: CanvasRenderingContext2D) {
    const padding = 60
    const gap = 40
    const availWidth = this.width - padding * 2
    const top = this.contentTop - 10
    const bottom = this.contentBottom + 10

    ctx.strokeStyle = 'rgba(255,255,255,0.03)'
    ctx.lineWidth = 1

    if (this.params.layout === 'two-col') {
      const x = padding + (availWidth - gap) / 2 + gap / 2
      ctx.beginPath(); ctx.moveTo(x, top); ctx.lineTo(x, bottom); ctx.stroke()
    } else if (this.params.layout === 'three-col') {
      const colW = (availWidth - gap * 2) / 3
      for (let i = 1; i <= 2; i++) {
        const x = padding + colW * i + gap * (i - 0.5)
        ctx.beginPath(); ctx.moveTo(x, top); ctx.lineTo(x, bottom); ctx.stroke()
      }
    } else if (this.params.layout === 'asymmetric') {
      const sideW = availWidth * 0.32
      const x = padding + sideW + gap / 2
      ctx.beginPath(); ctx.moveTo(x, top); ctx.lineTo(x, bottom); ctx.stroke()
    }
  }
}

import type { PreparedTextWithSegments } from '@chenglou/pretext'
import { layoutWithLines } from '@chenglou/pretext'
import type { GlyphPosition } from './types.ts'

// Shared canvas context for measuring individual character widths
let measureCtx: CanvasRenderingContext2D | null = null
function getMeasureCtx(): CanvasRenderingContext2D {
  if (!measureCtx) {
    const c = document.createElement('canvas')
    measureCtx = c.getContext('2d')!
  }
  return measureCtx
}

/**
 * Compute per-character (x, y) positions by rendering each line's text
 * and measuring character widths via canvas. This avoids the kerning/shaping
 * drift from summing pretext's per-segment widths at the character level.
 *
 * Strategy: use pretext for line breaking (which lines, what width), then
 * use canvas measureText for exact character-level x positions within each line.
 */
export function computeGlyphPositions(
  prepared: PreparedTextWithSegments,
  maxWidth: number,
  lineHeight: number,
  offsetX: number = 0,
  offsetY: number = 0,
  font?: string,
): GlyphPosition[] {
  const result = layoutWithLines(prepared, maxWidth, lineHeight)
  const positions: GlyphPosition[] = []
  let globalIndex = 0

  const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' })
  const ctx = getMeasureCtx()
  if (font) ctx.font = font

  for (let lineIdx = 0; lineIdx < result.lines.length; lineIdx++) {
    const line = result.lines[lineIdx]!
    const y = lineIdx * lineHeight + offsetY
    const lineText = line.text

    // Split the line text into graphemes
    const graphemes = Array.from(segmenter.segment(lineText), s => s.segment)

    // Measure cumulative widths using canvas for accuracy (accounts for kerning)
    let x = offsetX
    let cumText = ''

    for (let gi = 0; gi < graphemes.length; gi++) {
      const char = graphemes[gi]!
      const isWhitespace = /^\s+$/.test(char)

      // Measure width of this character in context
      const prevWidth = ctx.measureText(cumText).width
      cumText += char
      const newWidth = ctx.measureText(cumText).width
      const charWidth = newWidth - prevWidth

      if (!isWhitespace) {
        positions.push({
          char,
          globalIndex,
          x,
          y,
          width: charWidth,
          lineIndex: lineIdx,
          segmentIndex: 0,
        })
      }

      x += charWidth
      globalIndex++
    }
  }

  return positions
}

/**
 * Compute the layout height for centering purposes
 */
export function getLayoutInfo(
  prepared: PreparedTextWithSegments,
  maxWidth: number,
  lineHeight: number,
) {
  const result = layoutWithLines(prepared, maxWidth, lineHeight)
  return {
    height: result.height,
    lineCount: result.lineCount,
    lines: result.lines,
  }
}

import type { GlyphPosition, AnimatedGlyph, EffectName, EffectParams } from './types.ts'
import { effects } from './effects.ts'
import { Renderer } from './renderer.ts'

export class Animator {
  private renderer: Renderer
  private rafId: number = 0
  private startTime: number = 0
  private running: boolean = false
  private continuous: boolean = false

  private fromGlyphs: GlyphPosition[] = []
  private toGlyphs: GlyphPosition[] = []
  private currentEffect: EffectName = 'morph'
  private font: string = ''
  private color: string = '#f0f0f0'

  // Layout guide
  private guideX: number = 0
  private guideY: number = 0
  private guideWidth: number = 0
  private guideHeight: number = 0

  params: EffectParams = {
    duration: 1200,
    stagger: 30,
    easing: 'easeInOutCubic',
    scatterRadius: 400,
    rotationIntensity: 3,
    waveAmplitude: 20,
    waveFrequency: 3,
    waveSpeed: 2,
  }

  constructor(renderer: Renderer) {
    this.renderer = renderer
  }

  setFont(font: string) {
    this.font = font
  }

  setColor(color: string) {
    this.color = color
  }

  setGlyphs(from: GlyphPosition[], to: GlyphPosition[]) {
    this.fromGlyphs = from
    this.toGlyphs = to
  }

  setEffect(effect: EffectName) {
    this.currentEffect = effect
    this.continuous = effect === 'wave'
  }

  setGuide(x: number, y: number, width: number, height: number) {
    this.guideX = x
    this.guideY = y
    this.guideWidth = width
    this.guideHeight = height
  }

  play() {
    this.startTime = performance.now()
    this.running = true
    if (!this.rafId) this.tick()
  }

  stop() {
    this.running = false
    if (this.rafId) {
      cancelAnimationFrame(this.rafId)
      this.rafId = 0
    }
  }

  // Render the "to" state as-is (static display)
  renderStatic() {
    const glyphs: AnimatedGlyph[] = this.toGlyphs.map(g => ({
      char: g.char,
      x: g.x,
      y: g.y,
      width: g.width,
      opacity: 1,
      scale: 1,
      rotation: 0,
    }))
    this.draw(glyphs)
  }

  private draw(glyphs: AnimatedGlyph[]) {
    this.renderer.clear()
    if (this.guideWidth > 0) {
      this.renderer.drawWidthGuide(this.guideX, this.guideY, this.guideWidth, this.guideHeight)
    }
    this.renderer.drawGlyphs(glyphs, this.font, this.color)
  }

  private tick = () => {
    if (!this.running) {
      this.rafId = 0
      return
    }

    const now = performance.now()
    const elapsed = now - this.startTime
    const duration = this.params.duration

    let t: number
    if (this.continuous) {
      t = 1 // Wave uses time, not t
    } else {
      t = Math.min(elapsed / duration, 1)
    }

    const glyphs = effects[this.currentEffect](
      this.fromGlyphs,
      this.toGlyphs,
      t,
      now,
      this.params,
    )
    this.draw(glyphs)

    if (t < 1 || this.continuous) {
      this.rafId = requestAnimationFrame(this.tick)
    } else {
      this.running = false
      this.rafId = 0
    }
  }

  get isRunning() {
    return this.running
  }
}

import { prepareWithSegments, type PreparedTextWithSegments } from '@chenglou/pretext'
import { computeGlyphPositions, getLayoutInfo } from './layout-mapper.ts'
import { Renderer } from './renderer.ts'
import { Animator } from './animator.ts'
import { LavaExperiment } from './lava.ts'
import type { EffectName, EasingName } from './types.ts'

// ============================================================
// VIEW SWITCHING
// ============================================================
let currentView = 'animations'
const navTabs = document.querySelectorAll('.nav-tab')
const panelToggle = document.getElementById('panelToggle') as HTMLButtonElement
const animCanvas = document.getElementById('animCanvas') as HTMLCanvasElement
const lavaCanvas = document.getElementById('lavaCanvas') as HTMLCanvasElement
const animPanel = document.getElementById('animPanel') as HTMLDivElement
const lavaPanel = document.getElementById('lavaPanel') as HTMLDivElement

function switchView(view: string) {
  if (view === currentView) return
  currentView = view

  // Nav tabs
  navTabs.forEach(t => t.classList.toggle('active', (t as HTMLElement).dataset.view === view))

  // Canvases
  animCanvas.classList.toggle('hidden', view !== 'animations')
  lavaCanvas.classList.toggle('hidden', view !== 'lava')

  // Panels — close all, swap which one is available
  animPanel.classList.remove('open')
  lavaPanel.classList.remove('open')
  animPanel.classList.toggle('wrong-view', view !== 'animations')
  lavaPanel.classList.toggle('wrong-view', view !== 'lava')
  panelToggle.classList.remove('hidden')

  // Stop/start the right experiment
  if (view === 'animations') {
    lava.stop()
    renderStatic()
  } else {
    animator.stop()
    lava.resize()
    lava.start()
  }
}

navTabs.forEach(tab => {
  tab.addEventListener('click', () => switchView((tab as HTMLElement).dataset.view!))
})

// Panel toggle/close
panelToggle.addEventListener('click', () => {
  const panel = currentView === 'animations' ? animPanel : lavaPanel
  panel.classList.add('open')
  panelToggle.classList.add('hidden')
})

document.querySelectorAll('[data-close]').forEach(btn => {
  btn.addEventListener('click', () => {
    animPanel.classList.remove('open')
    lavaPanel.classList.remove('open')
    panelToggle.classList.remove('hidden')
  })
})

// ============================================================
// ANIMATIONS EXPERIMENT (existing)
// ============================================================
let prepared: PreparedTextWithSegments | null = null
let currentText =
  'Words that explode, reassemble, flow like water. Since you know exact line breaks and widths at any container size, you can smoothly animate text between layouts — morphing from one column width to another, or having text pour into a shape.'

let fontSize = 32
let lineHeightMultiplier = 1.5
let layoutWidth = 600
let prevLayoutWidth = 300

const fontFamily = 'Inter, system-ui, sans-serif'
const fontWeight = '600'

function getFont() { return `${fontWeight} ${fontSize}px ${fontFamily}` }
function getLineHeight() { return Math.round(fontSize * lineHeightMultiplier) }

const renderer = new Renderer(animCanvas)
const animator = new Animator(renderer)
animator.setColor('#f0f0f0')

// Effect buttons
const effectGrid = document.getElementById('effectGrid')!
effectGrid.addEventListener('click', (e) => {
  const btn = (e.target as HTMLElement).closest('.effect-btn') as HTMLElement | null
  if (!btn) return
  effectGrid.querySelectorAll('.effect-btn').forEach(b => b.classList.remove('active'))
  btn.classList.add('active')
  const effect = btn.dataset.effect as EffectName
  animator.setEffect(effect)
  updateEffectControls(effect)
  playCurrentEffect()
})

// Sliders
function bindSlider(id: string, valId: string, fmt: (v: number) => string, cb: (v: number) => void) {
  const s = document.getElementById(id) as HTMLInputElement
  const v = document.getElementById(valId) as HTMLSpanElement
  if (!s || !v) return
  s.addEventListener('input', () => { const n = parseFloat(s.value); v.textContent = fmt(n); cb(n) })
}

bindSlider('widthSlider', 'widthValue', v => String(v), v => { prevLayoutWidth = layoutWidth; layoutWidth = v; recomputeAndAnimate() })
bindSlider('fontSizeSlider', 'fontSizeValue', v => String(v), v => { fontSize = v; reprepareAndAnimate() })
bindSlider('lineHeightSlider', 'lineHeightValue', v => (v / 100).toFixed(1), v => { lineHeightMultiplier = v / 100; recomputeAndAnimate() })
bindSlider('durationSlider', 'durationValue', v => (v / 1000).toFixed(1) + 's', v => { animator.params.duration = v })
bindSlider('staggerSlider', 'staggerValue', v => String(v), v => { animator.params.stagger = v })

const easingSelect = document.getElementById('easingSelect') as HTMLSelectElement
easingSelect?.addEventListener('change', () => { animator.params.easing = easingSelect.value as EasingName })

const textInput = document.getElementById('textInput') as HTMLTextAreaElement
textInput.value = currentText
let textDebounce: ReturnType<typeof setTimeout>
textInput?.addEventListener('input', () => {
  clearTimeout(textDebounce)
  textDebounce = setTimeout(() => { currentText = textInput.value; reprepareAndAnimate() }, 300)
})

document.getElementById('playBtn')?.addEventListener('click', () => playCurrentEffect())
document.getElementById('resetBtn')?.addEventListener('click', () => { animator.stop(); renderStatic() })

function updateEffectControls(effect: EffectName) {
  const inner = document.getElementById('effectControlsInner')!
  const section = document.getElementById('effectControls')!
  const configs: Record<string, string> = {
    morph: '', pour: '', typewriter: '', vortex: '',
    explode: `
      <div class="slider-row"><span class="slider-label">Scatter</span><input type="range" id="scatterSlider" min="100" max="1000" value="${animator.params.scatterRadius}" /><span class="slider-value" id="scatterValue">${animator.params.scatterRadius}</span></div>
      <div class="slider-row"><span class="slider-label">Rotation</span><input type="range" id="rotationSlider" min="0" max="10" value="${animator.params.rotationIntensity}" step="0.5" /><span class="slider-value" id="rotationValue">${animator.params.rotationIntensity}</span></div>`,
    wave: `
      <div class="slider-row"><span class="slider-label">Amplitude</span><input type="range" id="waveAmpSlider" min="2" max="60" value="${animator.params.waveAmplitude}" /><span class="slider-value" id="waveAmpValue">${animator.params.waveAmplitude}</span></div>
      <div class="slider-row"><span class="slider-label">Frequency</span><input type="range" id="waveFreqSlider" min="1" max="10" value="${animator.params.waveFrequency}" step="0.5" /><span class="slider-value" id="waveFreqValue">${animator.params.waveFrequency}</span></div>
      <div class="slider-row"><span class="slider-label">Speed</span><input type="range" id="waveSpeedSlider" min="0.5" max="8" value="${animator.params.waveSpeed}" step="0.5" /><span class="slider-value" id="waveSpeedValue">${animator.params.waveSpeed}</span></div>`,
  }
  const html = configs[effect] ?? ''
  inner.innerHTML = html
  section.style.display = html ? 'block' : 'none'
  if (effect === 'explode') {
    bindDyn('scatterSlider', 'scatterValue', v => String(v), v => { animator.params.scatterRadius = v })
    bindDyn('rotationSlider', 'rotationValue', v => String(v), v => { animator.params.rotationIntensity = v })
  }
  if (effect === 'wave') {
    bindDyn('waveAmpSlider', 'waveAmpValue', v => String(v), v => { animator.params.waveAmplitude = v })
    bindDyn('waveFreqSlider', 'waveFreqValue', v => String(v), v => { animator.params.waveFrequency = v })
    bindDyn('waveSpeedSlider', 'waveSpeedValue', v => String(v), v => { animator.params.waveSpeed = v })
  }
}

function bindDyn(id: string, valId: string, fmt: (v: number) => string, cb: (v: number) => void) {
  const s = document.getElementById(id) as HTMLInputElement | null
  const v = document.getElementById(valId)
  if (!s || !v) return
  s.addEventListener('input', () => { const n = parseFloat(s.value); v.textContent = fmt(n); cb(n) })
}

function prepareCurrent() { prepared = prepareWithSegments(currentText, getFont()); animator.setFont(getFont()) }

function computePositions(width: number) {
  if (!prepared) return []
  const lh = getLineHeight()
  const info = getLayoutInfo(prepared, width, lh)
  const offsetX = (renderer.width - width) / 2
  const offsetY = (renderer.height - info.height) / 2
  animator.setGuide(offsetX, offsetY, width, info.height)
  return computeGlyphPositions(prepared, width, lh, offsetX, offsetY, getFont())
}

function recomputeAndAnimate() {
  if (!prepared) return
  animator.setGlyphs(computePositions(prevLayoutWidth), computePositions(layoutWidth))
  animator.play()
}

function reprepareAndAnimate() { prepareCurrent(); recomputeAndAnimate() }

let morphFlip = false
function playCurrentEffect() {
  if (!prepared) return
  const activeBtn = effectGrid.querySelector('.effect-btn.active') as HTMLElement
  const effect = (activeBtn?.dataset.effect ?? 'morph') as EffectName
  if (effect === 'morph') {
    const narrow = Math.max(100, Math.round(layoutWidth * 0.45))
    const wA = morphFlip ? layoutWidth : narrow
    const wB = morphFlip ? narrow : layoutWidth
    morphFlip = !morphFlip
    animator.setGlyphs(computePositions(wA), computePositions(wB))
  } else {
    const to = computePositions(layoutWidth)
    animator.setGlyphs(to, to)
  }
  animator.play()
}

function renderStatic() {
  if (!prepared) return
  const to = computePositions(layoutWidth)
  animator.setGlyphs(to, to)
  animator.renderStatic()
}

// ============================================================
// CURSOR IS LAVA EXPERIMENT
// ============================================================
const lava = new LavaExperiment(lavaCanvas)

// Lava controls
const lavaLayoutSelect = document.getElementById('lavaLayout') as HTMLSelectElement
lavaLayoutSelect?.addEventListener('change', () => {
  lava.setLayout(lavaLayoutSelect.value as 'two-col' | 'three-col' | 'asymmetric' | 'single')
})

bindSlider('lavaFontSize', 'lavaFontSizeValue', v => String(v), v => { lava.setFontSize(v) })
bindSlider('lavaRadius', 'lavaRadiusValue', v => String(v), v => { lava.params.radius = v })
bindSlider('lavaForce', 'lavaForceValue', v => String(v), v => { lava.params.force = v })
bindSlider('lavaSpring', 'lavaSpringValue', v => String(v), v => { lava.params.spring = v })
bindSlider('lavaDamping', 'lavaDampingValue', v => (v / 100).toFixed(2), v => { lava.params.damping = v })

// Toggles
function bindToggle(id: string, cb: (on: boolean) => void) {
  const btn = document.getElementById(id)
  if (!btn) return
  btn.addEventListener('click', () => {
    btn.classList.toggle('on')
    cb(btn.classList.contains('on'))
  })
}
bindToggle('lavaHeatToggle', on => { lava.params.heatEnabled = on })
bindToggle('lavaRotateToggle', on => { lava.params.rotateEnabled = on })

// Lava text input
const lavaTextInput = document.getElementById('lavaTextInput') as HTMLTextAreaElement
let lavaTextDebounce: ReturnType<typeof setTimeout>
lavaTextInput?.addEventListener('input', () => {
  clearTimeout(lavaTextDebounce)
  lavaTextDebounce = setTimeout(() => { lava.setText(lavaTextInput.value) }, 300)
})

// ============================================================
// RESIZE
// ============================================================
window.addEventListener('resize', () => {
  renderer.resize()
  const ws = document.getElementById('widthSlider') as HTMLInputElement
  if (ws) ws.max = String(Math.floor(renderer.width * 0.9))
  if (currentView === 'animations') renderStatic()
  if (currentView === 'lava') lava.resize()
})

// ============================================================
// INIT
// ============================================================
async function init() {
  await document.fonts.ready

  // Animations
  prepareCurrent()
  const ws = document.getElementById('widthSlider') as HTMLInputElement
  if (ws) ws.max = String(Math.floor(renderer.width * 0.9))
  animator.setEffect('morph')
  updateEffectControls('morph')
  const to = computePositions(layoutWidth)
  animator.setGlyphs(to, to)
  animator.setEffect('pour')
  animator.params.duration = 1800
  const pourBtn = effectGrid.querySelector('[data-effect="pour"]') as HTMLElement
  effectGrid.querySelectorAll('.effect-btn').forEach(b => b.classList.remove('active'))
  pourBtn?.classList.add('active')
  updateEffectControls('pour')
  animator.play()
  setTimeout(() => {
    const morphBtn = effectGrid.querySelector('[data-effect="morph"]') as HTMLElement
    effectGrid.querySelectorAll('.effect-btn').forEach(b => b.classList.remove('active'))
    morphBtn?.classList.add('active')
    animator.setEffect('morph')
    animator.params.duration = 1200
    updateEffectControls('morph')
  }, 2200)

  // Lava — prepare text but don't start until switched to
  lava.setText(lavaTextInput.value)
}

init()

import type { EasingFn, EasingName } from './types.ts'

export function linear(t: number): number {
  return t
}

export function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
}

export function easeInOutQuad(t: number): number {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2
}

export function easeOutElastic(t: number): number {
  if (t === 0 || t === 1) return t
  const c4 = (2 * Math.PI) / 3
  return Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1
}

export function easeOutBounce(t: number): number {
  const n1 = 7.5625
  const d1 = 2.75
  if (t < 1 / d1) return n1 * t * t
  if (t < 2 / d1) return n1 * (t -= 1.5 / d1) * t + 0.75
  if (t < 2.5 / d1) return n1 * (t -= 2.25 / d1) * t + 0.9375
  return n1 * (t -= 2.625 / d1) * t + 0.984375
}

export const easings: Record<EasingName, EasingFn> = {
  linear,
  easeInOutCubic,
  easeInOutQuad,
  easeOutElastic,
  easeOutBounce,
}
